import{_ as o,o as r,c as t,a5 as a}from"./chunks/framework.DJo0M80U.js";const i=JSON.parse('{"title":"未捕获错误（Uncaught Errors）的新行为","description":"这一改变具有重要意义， 自 React 16 起，任何未被错误边界捕获的错误将会导致整个 React 组件树被卸载。 我们对这一决定有过一些争论，但根据我们的经验，把一个错误的 UI 留在那比完全移除它要更糟糕。例如，在类似 Messenger 的产品中，把一个异常的 UI 展示。","frontmatter":{"title":"未捕获错误（Uncaught Errors）的新行为","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","工程化、质量与性能"],"description":"这一改变具有重要意义， 自 React 16 起，任何未被错误边界捕获的错误将会导致整个 React 组件树被卸载。 我们对这一决定有过一些争论，但根据我们的经验，把一个错误的 UI 留在那比完全移除它要更糟糕。例如，在类似 Messenger 的产品中，把一个异常的 UI 展示。","sidebarWeight":73,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/错误处理/未捕获错误（Uncaught Errors）的新行为.md"},"headers":[],"relativePath":"posts/Vue系统教程/06-工程化、质量与性能/未捕获错误（Uncaught Errors）的新行为.md","filePath":"posts/Vue系统教程/06-工程化、质量与性能/未捕获错误（Uncaught Errors）的新行为.md"}'),s={name:"posts/Vue系统教程/06-工程化、质量与性能/未捕获错误（Uncaught Errors）的新行为.md"};function c(n,e,d,_,u,g){return r(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="未捕获错误-uncaught-errors-的新行为" tabindex="-1">未捕获错误（Uncaught Errors）的新行为 <a class="header-anchor" href="#未捕获错误-uncaught-errors-的新行为" aria-label="Permalink to &quot;未捕获错误（Uncaught Errors）的新行为&quot;">​</a></h1><blockquote><p>本节目标：理解“未捕获错误（Uncaught Errors）的新行为”的核心思路，并能把它用于实际开发或面试表达。 这一改变具有重要意义，<strong>自</strong> <code>React 16</code> <strong>起，任何未被错误边界捕获的错误将会导致整个</strong> <code>React</code> <strong>组件树被卸载。</strong></p></blockquote><p>我们对这一决定有过一些争论，但根据我们的经验，把一个错误的 <code>UI</code> 留在那比完全移除它要更糟糕。例如，在类似 <code>Messenger</code> 的产品中，把一个异常的 <code>UI</code> 展示给用户可能会导致用户将信息错发给别人。同样，对于支付类应用而言，显示错误的金额也比不呈现任何内容更糟糕。</p><p>此变化意味着当你迁移到 <code>React 16</code> 时，你可能会发现一些已存在你应用中但未曾注意到的崩溃。增加错误边界能够让你在应用发生异常时提供更好的用户体验。</p><p>例如，<code>Facebook Messenger</code> 将侧边栏、信息面板、聊天记录以及信息输入框包装在单独的错误边界中。如果其中的某些 <code>UI</code> 组件崩溃，其余部分仍然能够交互。 我们也鼓励使用 <code>JS</code> 错误报告服务（或自行构建），这样你能了解关于生产环境中出现的未捕获异常，并将其修复。</p></div>',1)])])}const h=o(s,[["render",c]]);export{i as __pageData,h as default};
